<?php
declare(strict_types=1);
use Hostider\OfflineBackup\{Workspace,Guard,NativeSchema,Rehearsal,StreamArchive,Image};
use Hostider\Core\Id;
require __DIR__.'/harness.php';require __DIR__.'/database.php';require __DIR__.'/offline-backup-fixture.php';
test('F6-F 01 actual complete encrypted native backup contains no plaintext secret',function():void{$f=ffFixture();$before=ffHash($f['w']);$f['w']->seal();$report=Rehearsal::backup($f['w'],$f['key']);same('OFFLINE_ENCRYPTED_BACKUP_COMPLETE',$report['status']);same(2,$report['files']);same(true,$report['rows']>100);same(true,$report['finance']['balanced']);same($before,ffHash($f['w']));$cipher=file_get_contents($f['w']->root.'/backup.bin');foreach([$f['key'],$f['private']['app_key'],$f['private']['password'],'F6F_SECRET_MESSAGE_CANARY','F6F_SECRET_CUSTOMER_CANARY','F6F_SECRET_PDF_CANARY'] as $secret){if($secret!==''){same(false,str_contains($cipher,$secret));same(false,str_contains(json_encode($report),$secret));}}same(false,file_exists($f['w']->root.'/backup.partial'));$GLOBALS['ff_base']=$f;});
test('F6-F 02 real isolated native restore matches every row file schema and ledger',function():void{$f=ffFixture();$f['w']->seal();$source=ffHash($f['w']);$backup=Rehearsal::backup($f['w'],$f['key']);$allocated=false;$restored=Rehearsal::restore($f['w'],$f['key'],function($stage)use(&$allocated):void{if($stage==='target_created'){$allocated=true;}});same(true,$allocated);same('ISOLATED_RESTORE_REHEARSAL_COMPLETE',$restored['status']);same($backup['manifest_sha256'],$restored['manifest_sha256']);same($source,ffHash($f['w'],'target'));same($source,ffHash($f['w']));same(hash('sha256',$f['pdf']),hash_file('sha256',$f['w']->fileRoot('documents',true).'/'.$f['upload'].'.pdf'));same(hash_file('sha256',$f['w']->fileRoot('attachments').'/'.$f['attachment']['id'].'.bin'),hash_file('sha256',$f['w']->fileRoot('attachments',true).'/'.$f['attachment']['id'].'.bin'));same(true,$restored['finance']['balanced']);same(false,$restored['effects_allowed']);$GLOBALS['ff_restored']=$f;});

test('F6-F 03 independently reopened native target has current57 migrations and exact rows',function():void{$f=$GLOBALS['ff_restored'];$w=Workspace::load($f['w']->id,$f['private']);$db=$w->db('target');$m=new \Hostider\Core\Database\Migrator($db,dirname(__DIR__).'/migrations');$m->assertReady();same([],$m->migrate());same(57,(int)$db->execute('SELECT COUNT(*) FROM schema_migrations')->fetchColumn());same(ffHash($w),ffHash($w,'target'));});
test('F6-F 04 native restored attachment decrypts to exact original checksum',function():void{$f=$GLOBALS['ff_restored'];$store=new \Hostider\Support\Mail\FileStore($f['w']->fileRoot('attachments',true),dirname(__DIR__).'/public',new \Hostider\Core\Security\Crypto($f['w']->applicationKey()));$bytes=\Hostider\Support\Mail\Attachments::FIXTURE;same($bytes,$store->read($f['attachment']['id'],strlen($bytes),hash('sha256',$bytes)));});
test('F6-F 05 native official PDF bytes and encrypted metadata restore correctly',function():void{$f=$GLOBALS['ff_restored'];$store=new \Hostider\Billing\DocumentStore($f['w']->fileRoot('documents',true),dirname(__DIR__).'/public');same($f['pdf'],$store->read($f['upload'],strlen($f['pdf'])));$cfg=$f['w']->appConfig();$documents=new \Hostider\Billing\DocumentService($f['w']->db('target'),$cfg,$store,new \Hostider\Billing\Repository($f['w']->db('target')));same($f['pdf'],$documents->download($f['document'],$f['client']['customer'])['bytes']);});
test('F6-F 06 wrong256 bit key rejects before target allocation',function():void{ffBadArchive(fn($f)=>file_get_contents($f['w']->root.'/backup.bin'),'F6F_AUTHENTICATION',random_bytes(32));});
test('F6-F 07 modified ciphertext rejects before any restore effects',function():void{ffBadArchive(function($f){$b=file_get_contents($f['w']->root.'/backup.bin');$b[strlen($b)-1]=chr(ord($b[strlen($b)-1])^1);return $b;},'F6F_AUTHENTICATION');});
test('F6-F 08 truncated ciphertext cannot be mistaken for a complete backup',function():void{ffBadArchive(fn($f)=>substr(file_get_contents($f['w']->root.'/backup.bin'),0,-12),'F6F_TRUNCATED');});
test('F6-F 09 authenticated but altered final manifest is rejected',function():void{ffBadArchive(fn($f)=>ffRepack($f,function($r){++$r[count($r)-1]['content']['rows'];return $r;},false),'F6F_MANIFEST_INTEGRITY');});
test('F6-F 10 authenticated missing registered file cannot pass a recomputed manifest',function():void{ffBadArchive(fn($f)=>ffRepack($f,function($rows){$skip=null;$out=[];foreach($rows as $r){if($r['kind']==='file'&&$skip===null){$skip=$r['key'];continue;}if($r['kind']==='chunk'&&$r['key']===$skip){continue;}$out[]=$r;}return $out;},true),'F6F_FILE_CATALOG');});
test('F6-F 11 traversal in an authenticated file record never escapes private target',function():void{ffBadArchive(fn($f)=>ffRepack($f,function($rows){foreach($rows as &$r){if($r['kind']==='file'){$r['meta']['name']='../../outside.pdf';break;}}return $rows;},false),'F6F_FILE_NAME');});
test('F6-F 12 nonroot source permissions are enforced without changing existing DB data',function():void{$f=ffFixture();$f['w']->seal();$p=$f['w']->fileRoot('documents').'/'.$f['upload'].'.pdf';same(true,chmod($p,0000));clearstatcache(true,$p);same(false,is_readable($p));try{ffReject($f,fn()=>Rehearsal::backup($f['w'],$f['key']));same('FAILED',$f['w']->state()['backup']);same(false,file_exists($f['w']->root.'/backup.bin'));}finally{chmod($p,0400);}});
test('F6-F 13 actual insufficient tmpfs free space blocks backup before export',function():void{$f=ffFixture(false);$f['w']->seal();$before=ffHash($f['w']);$p=$f['w']->root.'/space-pressure';$h=Guard::open($p,'x+b');$allocated=0;try{while(disk_free_space($f['w']->root)>=Guard::RESERVE){same(true,$allocated<469762048);Guard::write($h,str_repeat("\0",2097152));$allocated+=2097152;}same(true,disk_free_space($f['w']->root)<Guard::RESERVE);$e=raises(Throwable::class,fn()=>Rehearsal::backup($f['w'],$f['key']));same('F6F_DISK_SPACE',$e->getMessage());same($before,ffHash($f['w']));same(false,file_exists($f['w']->root.'/backup.bin'));}finally{fclose($h);same(true,unlink($p));}});
test('F6-F 14 real competing DB mutation is blocked during the read locked snapshot',function():void{$f=ffFixture();$f['w']->seal();$before=ffHash($f['w']);$observed=null;$report=Rehearsal::backup($f['w'],$f['key'],function($stage)use($f,&$observed):void{if($stage==='locked'){$observed=ffJoin(ffSpawn($f,['mode'=>'writer','ticket'=>$f['ticket']['id']]));}});same('WRITE_BLOCKED',$observed['status']);same(true,in_array($observed['native_error'],[1205,1969],true));same('OFFLINE_ENCRYPTED_BACKUP_COMPLETE',$report['status']);same($before,ffHash($f['w']));});
test('F6-F 15 noncooperating file change during capture cannot produce success',function():void{$f=ffFixture();$f['w']->seal();$before=ffHash($f['w']);$p=$f['w']->fileRoot('documents').'/'.$f['upload'].'.pdf';$changed=false;$e=raises(Throwable::class,function()use($f,$p,&$changed){return Rehearsal::backup($f['w'],$f['key'],function($stage)use($p,&$changed):void{if($stage==='export_file'&&!$changed){$changed=true;chmod($p,0600);$h=fopen($p,'ab');fwrite($h,'CHANGED');fclose($h);chmod($p,0400);}});});same(true,$changed);same('F6F_FILE_LOGICAL_INTEGRITY',$e->getMessage());same($before,ffHash($f['w']));same('FAILED',$f['w']->state()['backup']);same(false,file_exists($f['w']->root.'/backup.bin'));same(false,file_exists($f['w']->root.'/backup.partial'));});
test('F6-F 16 partial export fault leaves no complete archive and preserves source',function():void{$f=ffFixture();$f['w']->seal();$before=ffHash($f['w']);$e=raises(Throwable::class,fn()=>Rehearsal::backup($f['w'],$f['key'],function($stage):void{if($stage==='export_row'){throw new RuntimeException('F6F_INJECTED_EXPORT');}}));same('F6F_INJECTED_EXPORT',$e->getMessage());same($before,ffHash($f['w']));same('FAILED',$f['w']->state()['backup']);same(false,file_exists($f['w']->root.'/backup.bin'));same(false,file_exists($f['w']->root.'/backup.partial'));$f['w']->cleanup();same('OFFLINE_ENCRYPTED_BACKUP_COMPLETE',Rehearsal::backup($f['w'],$f['key'])['status']);});
test('F6-F 17 partial restore import fault deletes only new owned target and preserves source',function():void{$f=ffBackupFixture();$before=ffHash($f['w']);$e=raises(Throwable::class,fn()=>Rehearsal::restore($f['w'],$f['key'],function($stage):void{if($stage==='restore_row'){throw new RuntimeException('F6F_INJECTED_RESTORE');}}));same('F6F_INJECTED_RESTORE',$e->getMessage());same('FAILED',$f['w']->state()['target_state']);same(null,$f['w']->state()['target']);same(false,file_exists($f['w']->root.'/restored'));same($before,ffHash($f['w']));$f['w']->cleanup();same('ISOLATED_RESTORE_REHEARSAL_COMPLETE',Rehearsal::restore($f['w'],$f['key'])['status']);});
test('F6-F 18 completed restore replay and cleanup cannot overwrite existing target',function():void{$f=$GLOBALS['ff_restored'];$before=ffHash($f['w'],'target');$source=ffHash($f['w']);same('F6F_RESTORE_NO_REPLAY_OR_OVERWRITE',raises(Throwable::class,fn()=>Rehearsal::restore($f['w'],$f['key']))->getMessage());same('F6F_COMPLETED_TARGET_PRESERVED',raises(Throwable::class,fn()=>$f['w']->cleanup())->getMessage());same($before,ffHash($f['w'],'target'));same($source,ffHash($f['w']));});
test('F6-F 19 concurrent backup process is rejected without second archive or source writes',function():void{$f=ffFixture();$f['w']->seal();$before=ffHash($f['w']);$child=ffSpawn($f,['mode'=>'backup','stage'=>'locked']);try{ffReady($f);same('F6F_BUSY',raises(Throwable::class,fn()=>Rehearsal::backup($f['w'],$f['key']))->getMessage());}finally{ffRelease($f);}$r=ffJoin($child);same('OFFLINE_ENCRYPTED_BACKUP_COMPLETE',$r['status']);same($before,ffHash($f['w']));same(false,file_exists($f['w']->root.'/backup.partial'));same('F6F_BACKUP_NO_OVERWRITE',raises(Throwable::class,fn()=>Rehearsal::backup($f['w'],$f['key']))->getMessage());});
test('F6-F 20 production environment DSN and path inputs fail closed',function():void{$f=$GLOBALS['ff_base'];$before=ffHash($f['w']);putenv('APP_ENV=production');try{same('F6F_TEST_ONLY',raises(Throwable::class,fn()=>Rehearsal::restore($f['w'],$f['key']))->getMessage());}finally{putenv('APP_ENV=test');}$bad=$f['private'];$bad['dsn']='mysql:host=production;dbname=live';same('F6F_FIELDS',raises(Throwable::class,fn()=>Workspace::create($bad))->getMessage());same('F6F_OPERATION_ID',raises(Throwable::class,fn()=>Workspace::load('../../production',$f['private']))->getMessage());$r=ffCli($f,'status',['--restore-path=production']);same(1,$r['exit']);same('BLOCKED',$r['report']['status']);same($before,ffHash($f['w']));});
test('F6-F 21 real CLI seal backup restore never print key configuration or payload secrets',function():void{$f=ffFixture();foreach(['seal','backup','restore','verify'] as $command){$r=ffCli($f,$command);same(0,$r['exit']);same('',$r['stderr']);foreach([$f['key'],$f['private']['password'],$f['private']['app_key'],$f['private']['instance_token'],'F6F_SECRET_MESSAGE_CANARY','F6F_SECRET_PDF_CANARY'] as $v){if($v!==''){same(false,str_contains($r['stdout'],$v));}}}$f['w']=Workspace::load($f['w']->id,$f['private']);same(ffHash($f['w']),ffHash($f['w'],'target'));});
test('F6-F 22 authenticated migration mismatch rejects before target creation',function():void{ffBadArchive(fn($f)=>ffRepack($f,function($rows){$k=array_key_first($rows[0]['migrations']);$rows[0]['migrations'][$k]=str_repeat('0',64);return $rows;},true),'F6F_MIGRATION_OR_SCHEMA');});
test('F6-F 23 independent ledger sums match and unbalanced native source cannot be backed up',function():void{$f=$GLOBALS['ff_restored'];$sql='SELECT j.currency,l.side,CAST(SUM(l.amount_minor) AS CHAR) total FROM finance_lines l JOIN finance_journals j ON j.id=l.journal_id GROUP BY j.currency,l.side ORDER BY j.currency,l.side';$a=$f['db']->execute($sql)->fetchAll();$b=$f['w']->db('target')->execute($sql)->fetchAll();same($a,$b);same(2,count($a));same((string)$f['quote']['total_minor'],$a[0]['total']);$bad=ffFixture();$id=$bad['db']->execute('SELECT id FROM finance_journals LIMIT 1')->fetchColumn();$bad['db']->execute("INSERT INTO finance_lines(journal_id,account,side,amount_minor) VALUES (?,'cash','DEBIT',1)",[$id]);$before=ffHash($bad['w']);same('F6F_LEDGER_UNBALANCED',raises(Throwable::class,fn()=>$bad['w']->seal())->getMessage());same($before,ffHash($bad['w']));same(false,file_exists($bad['w']->root.'/backup.bin'));});
test('F6-F 24 audit copy is protected by verification fence and native message triggers remain',function():void{$f=$GLOBALS['ff_restored'];$target=$f['w']->db('target');$before=ffHash($f['w'],'target');same(true,(int)$target->execute('SELECT COUNT(*) FROM audit_logs')->fetchColumn()>0);same(1,(int)$target->execute('SELECT COUNT(*) FROM support_messages')->fetchColumn());$f['w']->model()->lock($target);try{raises(PDOException::class,fn()=>$target->execute('DELETE FROM audit_logs'));raises(PDOException::class,fn()=>$target->execute("UPDATE support_messages SET type='staff_reply'"));}finally{$target->execute('UNLOCK TABLES');}raises(PDOException::class,fn()=>$target->execute("UPDATE support_messages SET type='staff_reply'"));raises(PDOException::class,fn()=>$target->execute('DELETE FROM support_events'));same($before,ffHash($f['w'],'target'));same('RESTORED_TARGET_VERIFIED_READ_ONLY',Rehearsal::verify($f['w'],$f['key'])['status']);});
test('F6-F 25 killed backup leaves only ciphertext and owned cleanup preserves source',function():void{$f=ffFixture();$f['w']->seal();$before=ffHash($f['w']);$child=ffSpawn($f,['mode'=>'backup','stage'=>'export_row']);ffReady($f);same(true,proc_terminate($child[0],9));ffJoin($child,true);same(true,file_exists($f['w']->root.'/backup.partial'));$bytes=file_get_contents($f['w']->root.'/backup.partial');same(false,str_contains($bytes,'F6F_SECRET_MESSAGE_CANARY'));same(false,file_exists($f['w']->root.'/backup.bin'));$f['w']->cleanup();same(false,file_exists($f['w']->root.'/backup.partial'));same($before,ffHash($f['w']));});
test('F6-F 26 failure preserves an existing unowned path and refuses destructive cleanup',function():void{$f=$GLOBALS['ff_base'];$p=$f['w']->root.'/restored';Guard::mkdir($p);$h=Guard::open($p.'/existing','x+b');Guard::write($h,'SYNTHETIC_EXISTING_DATA');fclose($h);$before=ffHash($f['w']);try{same('F6F_RESTORE_NO_REPLAY_OR_OVERWRITE',raises(Throwable::class,fn()=>Rehearsal::restore($f['w'],$f['key']))->getMessage());same('F6F_UNOWNED_RESTORE_PATH',raises(Throwable::class,fn()=>$f['w']->cleanup())->getMessage());same('SYNTHETIC_EXISTING_DATA',file_get_contents($p.'/existing'));same($before,ffHash($f['w']));}finally{unlink($p.'/existing');rmdir($p);}});
test('F6-F 27 killed restore staging is anonymous and cleanup removes only owned quarantine',function():void{$f=ffBackupFixture();$before=ffHash($f['w']);$child=ffSpawn($f,['mode'=>'restore','stage'=>'restore_file_chunk']);ffReady($f);same(true,proc_terminate($child[0],9));ffJoin($child,true);foreach(['attachments','documents'] as $g){same([],array_values(array_diff(scandir($f['w']->fileRoot($g,true)),['.','..'])));}$f['w']->cleanup();same(false,file_exists($f['w']->root.'/restored'));same(null,$f['w']->state()['target']);same($before,ffHash($f['w']));});
test('F6-F 28 actual source symlink is rejected and unrelated bytes are preserved',function():void{$f=ffFixture();$p=$f['w']->root.'/unrelated';$h=Guard::open($p,'x+b');Guard::write($h,'SYNTHETIC_UNRELATED');fclose($h);$name=$f['w']->fileRoot('attachments').'/'.$f['attachment']['id'].'.bin';unlink($name);same(true,symlink($p,$name));$before=ffHash($f['w']);same('F6F_FILE',raises(Throwable::class,fn()=>$f['w']->seal())->getMessage());same('SYNTHETIC_UNRELATED',file_get_contents($p));same($before,ffHash($f['w']));});
test('F6-F 29 inconsistent orphan managed file cannot yield a quiescent backup',function():void{$f=ffFixture();$p=$f['w']->fileRoot('attachments').'/'.Id::uuid().'.bin';$h=Guard::open($p,'x+b');Guard::write($h,'SYNTHETIC_ORPHAN');fclose($h);$before=ffHash($f['w']);same('F6F_UNREGISTERED_FILE',raises(Throwable::class,fn()=>$f['w']->seal())->getMessage());same($before,ffHash($f['w']));same('SYNTHETIC_ORPHAN',file_get_contents($p));});
test('F6-F 30 authenticated schema SQL substitution is data and is never executed',function():void{ffBadArchive(fn($f)=>ffRepack($f,function($rows){foreach($rows as &$r){if($r['kind']==='table'){$r['schema']='DROP DATABASE production';break;}}return $rows;},true),'F6F_TABLE_SCHEMA');});
test('F6-F 31 authenticated row alteration and duplicate sequence reject before target',function():void{ffBadArchive(fn($f)=>ffRepack($f,function($rows){foreach($rows as &$r){if($r['kind']==='row'){$r['sha256']=str_repeat('0',64);break;}}return $rows;},false),'F6F_ROW_FRAME');ffBadArchive(fn($f)=>ffRepack($f,function($rows){foreach($rows as $i=>$r){if($r['kind']==='row'){array_splice($rows,$i+1,0,[$r]);break;}}return $rows;},false),'F6F_ROW_FRAME');});
test('F6-F 32 missing or expired dedicated instance pin cannot authorize operations',function():void{$f=$GLOBALS['ff_base'];$bad=$f['private'];$bad['instance_token']=bin2hex(random_bytes(32));same('F6F_DEDICATED_INSTANCE',raises(Throwable::class,fn()=>Workspace::load($f['w']->id,$bad))->getMessage());$root=integrationDb();$root->execute('UPDATE f6f_test_instance SET expires_at=DATE_SUB(UTC_TIMESTAMP(6),INTERVAL 1 SECOND)');try{same('F6F_DEDICATED_INSTANCE',raises(Throwable::class,fn()=>Rehearsal::restore($f['w'],$f['key']))->getMessage());}finally{$root->execute('UPDATE f6f_test_instance SET expires_at=TIMESTAMPADD(SECOND,3500,UTC_TIMESTAMP(6))');}});
test('F6-F 33 keygen uses private descriptor and generates distinct256 bit keys without stdout leak',function():void{$f=$GLOBALS['ff_base'];$keys=[];for($i=0;$i<2;++$i){$p=$f['w']->root.'/generated-key-'.$i;$h=Guard::open($p,'x+b');fclose($h);$pipes=[];$child=proc_open([PHP_BINARY,dirname(__DIR__).'/bin/offline-backup.php','keygen','--key-out-fd=3'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w'],3=>['file',$p,'r+']],$pipes,null,getenv());fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(0,proc_close($child));same('',$err);$key=file_get_contents($p);same(32,strlen($key));same(false,str_contains($out,$key));same('PRIVATE_KEY_GENERATED',json_decode($out,true,8,JSON_THROW_ON_ERROR)['status']);$keys[]=$key;}same(false,hash_equals($keys[0],$keys[1]));});
test('F6-F 34 missing physical registered source file cannot produce success',function():void{$f=ffFixture();$f['w']->seal();$before=ffHash($f['w']);$dir=$f['w']->fileRoot('documents');chmod($dir,0700);same(true,unlink($dir.'/'.$f['upload'].'.pdf'));chmod($dir,0500);same('F6F_MISSING_FILE',raises(Throwable::class,fn()=>Rehearsal::backup($f['w'],$f['key']))->getMessage());same($before,ffHash($f['w']));same(false,file_exists($f['w']->root.'/backup.bin'));same(false,file_exists($f['w']->root.'/backup.partial'));});
test('F6-F 35 privileged audit tamper is detected against authenticated backup without repair or source writes',function():void{$f=$GLOBALS['ff_restored'];$source=ffHash($f['w']);$target=$f['w']->db('target');same(true,(int)$target->execute('SELECT COUNT(*) FROM audit_logs')->fetchColumn()>0);$target->execute('DELETE FROM audit_logs');$tampered=ffHash($f['w'],'target');same('F6F_RESTORED_ROW_INTEGRITY',raises(Throwable::class,fn()=>Rehearsal::verify($f['w'],$f['key']))->getMessage());same($tampered,ffHash($f['w'],'target'));same($source,ffHash($f['w']));});
test('F6-F 36 keygen refuses a nonempty descriptor without overwriting existing bytes',function():void{$f=$GLOBALS['ff_base'];$p=$f['w']->root.'/existing-key';$h=Guard::open($p,'x+b');Guard::write($h,'PRESERVE_EXISTING_PRIVATE_BYTES');fclose($h);$pipes=[];$child=proc_open([PHP_BINARY,dirname(__DIR__).'/bin/offline-backup.php','keygen','--key-out-fd=3'],[0=>['pipe','r'],1=>['pipe','w'],2=>['pipe','w'],3=>['file',$p,'r+']],$pipes,null,getenv());fclose($pipes[0]);$out=stream_get_contents($pipes[1]);$err=stream_get_contents($pipes[2]);fclose($pipes[1]);fclose($pipes[2]);same(1,proc_close($child));same('',$err);same('BLOCKED',json_decode($out,true,8,JSON_THROW_ON_ERROR)['status']);same('PRESERVE_EXISTING_PRIVATE_BYTES',file_get_contents($p));});
foreach($GLOBALS['tests'] as $name=>$work){$GLOBALS['tests'][$name]=static function()use($work):void{try{$work();}catch(Throwable $e){$trace=array_slice(array_map(static fn($f)=>['function'=>$f['function']??'','class'=>$f['class']??'','file'=>basename($f['file']??'')],$e->getTrace()),0,8);echo 'F6F_OBSERVATION '.json_encode(['safe_stage'=>$GLOBALS['ff_stage']??'test','exception'=>get_class($e),'trace'=>$trace],JSON_THROW_ON_ERROR).PHP_EOL;throw $e;}};}
exit(executeTests(true));
